const seed = {
  profile:{name:'Alex Kim',title:'Computer Science Student',email:'alex.kim@example.com',location:'',college:'',degree:'',graduationYear:'',coursework:'',interests:'',experience:'',achievements:'',website:'',bio:'Aspiring full-stack developer who loves turning thoughtful ideas into useful products. Currently learning, building, and growing one project at a time.',github:'alexkim-dev',linkedin:'alex-kim-dev',leetcode:'alexkim',skills:['JavaScript','React','Node.js','Express','MongoDB','HTML & CSS','Git','REST APIs']},
  projects:[
    {name:'TaskFlow',description:'A collaborative task manager that helps small teams plan work, track progress, and celebrate wins.',tags:['React','Node.js','MongoDB'],status:'Completed',repo:'https://github.com/alexkim-dev/taskflow',demo:'https://taskflow.example.com'},
    {name:'Weatherly',description:'A clean weather dashboard with location search and a five-day forecast.',tags:['React','CSS','API'],status:'Completed',repo:'https://github.com/alexkim-dev/weatherly',demo:''},
    {name:'DevNotes',description:'A markdown-powered notebook built for developers and their everyday ideas.',tags:['JavaScript','Express','MongoDB'],status:'In progress',repo:'',demo:''},
    {name:'Color Studio',description:'An accessible color palette generator for designers and frontend developers.',tags:['HTML & CSS','JavaScript'],status:'Completed',repo:'',demo:''}
  ],
  certifications:[{name:'Meta Front-End Developer',issuer:'Meta · Coursera',date:'2025-04',credential:'',url:''},{name:'JavaScript Algorithms and Data Structures',issuer:'freeCodeCamp',date:'2025-02',credential:'',url:''}],
  role:'MERN Stack Developer', completed:[0,1], activities:[{icon:'✓',text:'Completed <strong>JavaScript Algorithms</strong>',time:'Yesterday'},{icon:'▧',text:'Added a new project, <strong>DevNotes</strong>',time:'2 days ago'},{icon:'✦',text:'Updated your <strong>developer profile</strong>',time:'4 days ago'}], analysis:null, public:true
};
let state;try{state={...seed,...JSON.parse(localStorage.getItem('devorbit-state')||'{}')};state.profile={...seed.profile,...(state.profile||{})};state.projects=state.projects||[];state.certifications=state.certifications||[];state.completed=state.completed||[]}catch{state=structuredClone(seed)}
const roles={
 'MERN Stack Developer':['JavaScript','React','Node.js','Express','MongoDB','REST APIs','Git','Authentication','Testing','Deployment'],
 'Frontend Developer':['JavaScript','React','HTML & CSS','Responsive design','Accessibility','Git','TypeScript','Testing','Performance','Design systems'],
 'Backend Developer':['Node.js','Express','REST APIs','MongoDB','SQL','Authentication','Testing','Docker','Cloud basics','Git'],
 'Data Analyst':['Python','SQL','Statistics','Excel','Data visualization','Pandas','Data cleaning','Power BI','Communication','Storytelling']
};
const lessons=[['JavaScript foundations','Review async JavaScript, closures, and modern syntax with focused exercises.','4 lessons · 3 hrs'],['React patterns','Build confidence with hooks, component composition, and state management.','5 lessons · 5 hrs'],['Build an API with Express','Design and document a REST API with validation and clear error handling.','Project · 6 hrs'],['MongoDB data modeling','Practice schema design, indexes, and aggregations using real examples.','4 lessons · 4 hrs'],['Ship your full-stack app','Connect your application, test the important flows, and deploy it.','Project · 8 hrs']];
function save(){localStorage.setItem('devorbit-state',JSON.stringify(state));const token=window.DevOrbitAuth?.token?.();if(token){clearTimeout(save.timer);save.timer=setTimeout(()=>fetch('/api/workspace',{method:'PUT',headers:{'Content-Type':'application/json',Authorization:`Bearer ${token}`},body:JSON.stringify(state)}).catch(()=>{}),250)}}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2600)}
function initials(name){return name.split(/\s+/).map(v=>v[0]).slice(0,2).join('').toUpperCase()||'DO'}
function setIdentity(){document.querySelectorAll('.avatar').forEach(a=>a.textContent=initials(state.profile.name));document.getElementById('sideName').textContent=state.profile.name;document.getElementById('projectNavCount').textContent=state.projects.length;document.getElementById('todayLabel').textContent=new Intl.DateTimeFormat('en',{weekday:'short',month:'short',day:'numeric'}).format(new Date())}
function card(title,body,extra=''){return `<section class="card"><div class="card-heading"><div><h2>${title}</h2></div>${extra}</div>${body}</section>`}
function metrics(){return `<div class="grid metrics-grid"><section class="card metric-card"><div class="metric-top">Projects <span class="metric-icon" style="background:#f1efff;color:#7562e9">▧</span></div><div class="metric-value">${state.projects.length.toString().padStart(2,'0')}</div><div class="metric-foot"><span class="positive">${state.projects.filter(p=>p.status==='Completed').length} completed</span> · keep building</div></section><section class="card metric-card"><div class="metric-top">Skills added <span class="metric-icon" style="background:#eaf8f1;color:#47ae82">⌘</span></div><div class="metric-value">${state.profile.skills.length.toString().padStart(2,'0')}</div><div class="metric-foot"><span class="positive">${state.profile.skills.length} on your profile</span> · nice progress</div></section><section class="card metric-card"><div class="metric-top">Certifications <span class="metric-icon" style="background:#fff5e9;color:#e99e42">♧</span></div><div class="metric-value">${state.certifications.length.toString().padStart(2,'0')}</div><div class="metric-foot">Your learning is adding up</div></section><section class="card metric-card"><div class="metric-top">Roadmap progress <span class="metric-icon" style="background:#edf5ff;color:#639fdf">⌁</span></div><div class="metric-value">${Math.round(state.completed.length/lessons.length*100)}<span style="font-size:15px;color:#8a8ca0">%</span></div><div class="metric-foot">${state.completed.length} of ${lessons.length} learning steps done</div></section></div>`}
function dashboard(){let required=roles[state.role],matched=required.filter(s=>state.profile.skills.includes(s)).length,pct=Math.round(matched/required.length*100),hour=new Date().getHours(),greeting=hour<12?'Good morning':hour<18?'Good afternoon':'Good evening';return `<div class="page-title-row"><div><p class="eyebrow">${new Intl.DateTimeFormat('en',{weekday:'long',month:'long',day:'numeric'}).format(new Date())}</p><h1 class="page-title">${greeting}, ${esc(state.profile.name.split(' ')[0])} <span style="font-size:23px">✦</span></h1><p class="page-subtitle">Here’s your career snapshot. Keep up the great momentum.</p></div><button class="primary-btn" data-page="skills"><span>✦</span> View career insights</button></div>${metrics()}<div class="grid dashboard-grid">${card('Career readiness',`<div class="score-body"><div class="donut" style="background:conic-gradient(var(--purple) 0 ${Math.min(pct+18,100)}%,#f0eff7 ${Math.min(pct+18,100)}% 100%)"><div class="donut-center"><strong>${Math.min(pct+18,100)}%</strong><span>readiness</span></div></div><div class="score-info"><div class="score-label"><i class="dot" style="background:#7562e9"></i> Profile strength <b>${Math.min(72+state.projects.length*2,100)}%</b></div><div class="score-label"><i class="dot" style="background:#48b88a"></i> Skills match <b>${pct}%</b></div><div class="score-label"><i class="dot" style="background:#efa950"></i> Learning progress <b>${Math.round(state.completed.length/lessons.length*100)}%</b></div></div></div><div class="score-insight">✦ <strong>Nice work!</strong> Your ${esc(state.role)} profile is taking shape. Add a few skills to strengthen your match.</div>`)}${card('Your momentum',`<div class="chart-wrap"><svg viewBox="0 0 500 180" preserveAspectRatio="none" aria-label="Career progress trend"><defs><linearGradient id="chartFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#8170ed" stop-opacity=".18"/><stop offset="1" stop-color="#8170ed" stop-opacity="0"/></linearGradient></defs><path class="chart-grid" d="M20 35H490M20 75H490M20 115H490M20 155H490"/><path class="chart-area" d="M20 145 C55 140 62 125 100 130 S152 108 180 116 S231 88 260 98 S310 69 340 79 S390 46 420 56 S460 32 490 39 V165 H20Z"/><path class="chart-line" d="M20 145 C55 140 62 125 100 130 S152 108 180 116 S231 88 260 98 S310 69 340 79 S390 46 420 56 S460 32 490 39"/><circle class="chart-dot" cx="490" cy="39" r="4"/></svg></div><div class="chart-labels"><span>May</span><span>Jun</span><span>Jul</span><span>Aug</span><span>Sep</span><span>Oct</span></div><p style="font-size:9px;color:#a1a2b0;text-align:center;margin:10px 0 0">Illustrative career activity · based on your recent profile updates</p>`,`<span class="pill">↗ Growing steadily</span>` )}</div><div class="grid bottom-grid">${projectCard()}${activityCard()}</div>`}
function projectCard(){let items=state.projects.slice(0,4);let body=items.length?`<div class="project-list">${items.map((p,i)=>`<div class="project-row"><div class="project-thumb" style="background:${['#f1efff','#eaf8f1','#fff4e8','#eef5ff'][i%4]};color:${['#7562e9','#48ab81','#e09b43','#6d9fd5'][i%4]}">${['▦','◉','⌘','✳'][i%4]}</div><div class="project-main"><strong>${esc(p.name)}</strong><span>${esc((p.tags||[]).slice(0,3).join(' · '))}</span></div><span class="project-status" style="${p.status==='In progress'?'background:#fff5e9;color:#dc963c':''}">${esc(p.status)}</span></div>`).join('')}</div>`:`<div class="empty-state"><strong>Your first project starts here</strong>Add a project to showcase what you can build.</div>`;return card('Recent projects',body,`<button class="text-link" data-page="projects">See all →</button>`)}
function activityCard(){return card('Recent activity',`<div class="activity-list">${state.activities.slice(0,4).map(a=>`<div class="activity-item"><div class="activity-icon">${a.icon}</div><div class="activity-copy">${a.text}<small>${esc(a.time)}</small></div></div>`).join('')||'<div class="empty-state">Your activity will appear here.</div>'}</div>`,`<button class="text-link" data-toast="You’re all caught up.">View all</button>`)}
function titleBlock(eyebrow,title,sub,button=''){return `<div class="page-title-row"><div><p class="eyebrow">${eyebrow}</p><h1 class="page-title">${title}</h1><p class="page-subtitle">${sub}</p></div>${button}</div>`}
function profilePage(){let fields=[['Full name','name'],['Professional title','title'],['Email address','email'],['Location','location'],['College or university','college'],['Degree / major','degree'],['Expected graduation year','graduationYear'],['Relevant coursework','coursework'],['Career interests','interests'],['Internship or work experience','experience'],['Awards and achievements','achievements'],['Personal website','website'],['GitHub username','github'],['LinkedIn profile','linkedin'],['LeetCode username','leetcode']];let pct=Math.min(100,Math.round((Object.values(state.profile).filter(v=>typeof v==='string'&&v.trim()).length+state.profile.skills.length)/22*100));return `${titleBlock('YOUR DEVELOPER IDENTITY','My profile','Add your academic background, experience, and interests to build a complete student portfolio.','<button class="primary-btn" data-action="save-profile">Save changes</button>')}<div class="grid two-col"><section class="card content-card"><div class="profile-head"><div class="profile-avatar">${initials(state.profile.name)}</div><div><h2>${esc(state.profile.name)}</h2><span>${esc(state.profile.title)} &middot; ${esc(state.profile.location)}</span></div></div><div style="display:flex;justify-content:space-between;font-size:10px;color:#85889a;margin-bottom:8px"><span>Profile completeness</span><strong>${pct}%</strong></div><div class="progress-track"><div class="progress-fill" style="width:${pct}%"></div></div><div class="divider"></div><form id="profileForm"><div class="grid two-col">${fields.map(([label,key])=>`<div class="field"><label for="p_${key}">${label}</label><input id="p_${key}" name="${key}" value="${esc(state.profile[key]||'')}" /></div>`).join('')}</div><div class="field"><label for="p_bio">About you</label><textarea id="p_bio" name="bio">${esc(state.profile.bio||'')}</textarea></div></form><button class="primary-btn" data-action="save-profile">Save profile</button></section><section class="card content-card"><h2>Your skills</h2><p class="muted">Skills you can confidently speak to. Add or remove them as you grow.</p><div id="skillTags" style="margin:13px 0">${state.profile.skills.map((s,i)=>`<span class="tag">${esc(s)} <button aria-label="Remove ${esc(s)}" data-action="remove-skill" data-index="${i}" style="border:0;background:none;color:inherit;padding:0 0 0 4px">?</button></span>`).join('')}</div><div class="field"><label for="newSkill">Add a skill</label><div style="display:flex;gap:7px"><input id="newSkill" placeholder="e.g. TypeScript"/><button class="secondary-btn" data-action="add-skill">Add</button></div></div><div class="divider"></div><h2 style="margin-bottom:8px">Developer profiles</h2><p class="muted">Add public links and import repositories from GitHub.</p><button class="secondary-btn" data-action="sync-github">Import GitHub repositories</button><div id="githubResult"></div></section></div>`}
function projectsPage(){return `${titleBlock('YOUR WORK, IN ONE PLACE','Projects','Show the ideas you made real. Add the details you want recruiters to see.','<button class="primary-btn" data-action="new-project">＋ Add project</button>')}<div class="grid two-col">${state.projects.map((p,i)=>`<section class="card content-card"><div style="display:flex;justify-content:space-between"><div class="project-thumb" style="background:${i%2?'#eaf8f1':'#f1efff'};color:${i%2?'#48ab81':'#7562e9'}">${i%2?'◉':'▦'}</div><button class="more-button" data-action="edit-project" data-index="${i}" aria-label="Edit project">•••</button></div><h2 style="margin-top:13px">${esc(p.name)}</h2><p class="muted">${esc(p.description)}</p><div>${(p.tags||[]).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><div class="divider"></div><div style="display:flex;justify-content:space-between;align-items:center"><span class="project-status" style="${p.status==='In progress'?'background:#fff5e9;color:#dc963c':''}">${esc(p.status)}</span><div style="display:flex;gap:10px">${p.repo?`<a class="text-link" target="_blank" rel="noreferrer" href="${esc(p.repo)}">Repository ↗</a>`:''}${p.demo?`<a class="text-link" target="_blank" rel="noreferrer" href="${esc(p.demo)}">Live demo ↗</a>`:''}</div></div></section>`).join('')||'<section class="card card-empty">Nothing here yet. Add a project to get started.</section>'}<section class="card content-card" style="border-style:dashed;display:grid;place-items:center;min-height:230px;text-align:center"><div><div class="tip-icon">＋</div><h2>Have something to show?</h2><p class="muted">Every project is another proof point.</p><button class="secondary-btn" data-action="new-project">Add a project</button></div></section></div><div class="grid section-gap">${card('Certifications',`<div class="project-list">${state.certifications.map((c,i)=>`<div class="project-row"><div class="project-thumb" style="background:#fff4e8;color:#e09b43">✦</div><div class="project-main"><strong>${esc(c.name)}</strong><span>${esc(c.issuer)} · ${esc(c.date||'Date not set')}</span></div><button class="text-link" data-action="delete-cert" data-index="${i}">Remove</button></div>`).join('')||'<div class="empty-state">Add certifications to your profile.</div>'}</div>`,'<button class="text-link" data-action="new-cert">＋ Add certification</button>')}</div>`}
function skillsPage(){let req=roles[state.role],matched=req.filter(s=>state.profile.skills.includes(s)),missing=req.filter(s=>!state.profile.skills.includes(s)),pct=Math.round(matched.length/req.length*100),other=state.profile.skills.filter(s=>!req.includes(s));return `${titleBlock('A CLEARER PATH FORWARD','Skill gap analysis','Compare your current skills with the requirements for the role you want.')}<section class="card content-card" style="margin-bottom:17px"><div class="role-head"><div><h2 style="font:700 14px Manrope;margin:0 0 5px">Target role</h2><span class="muted">Choose a role to see how your skills line up</span></div><select class="role-select" id="roleSelect">${Object.keys(roles).map(r=>`<option ${state.role===r?'selected':''}>${r}</option>`).join('')}</select></div><div class="divider"></div><div style="display:flex;align-items:center;gap:12px"><div class="role-score">${pct}<small>%</small></div><div style="flex:1"><strong style="font-size:11px">${matched.length} of ${req.length} required skills matched</strong><div class="progress-track" style="margin-top:9px"><div class="progress-fill" style="width:${pct}%"></div></div></div><button class="secondary-btn" data-action="refresh-analysis">Refresh analysis</button></div></section><div class="grid two-col"><section class="card content-card"><h2>Skills you have</h2><p class="muted">Matched against the ${esc(state.role)} role</p>${matched.map(s=>`<div class="skill-item"><span class="skill-check on">✓</span><span>${esc(s)}</span><span class="skill-level">On your profile</span></div>`).join('')||'<div class="card-empty">Add some role skills to your profile to see your match.</div>'}${other.map(s=>`<div class="skill-item"><span class="skill-check on">✓</span><span>${esc(s)}</span><span class="skill-level">Additional skill</span></div>`).join('')}</section><section class="card content-card"><h2>Skills to explore</h2><p class="muted">A suggested next step based on this role</p>${missing.map(s=>`<div class="skill-item"><span class="skill-check"></span><span>${esc(s)}</span><button class="text-link" data-action="learn-skill" data-skill="${esc(s)}">Add to skills</button></div>`).join('')||'<div class="pill" style="margin-top:16px">✦ All role skills matched — great work!</div>'}</section></div><section class="card content-card section-gap"><div style="display:flex;justify-content:space-between;align-items:center;gap:16px"><div><h2>Ready to work on a gap?</h2><p class="muted">Your roadmap turns learning goals into manageable steps.</p></div><button class="primary-btn" data-page="roadmap">Open my roadmap →</button></div></section>`}
function roadmapPage(){let pct=Math.round(state.completed.length/lessons.length*100);return `${titleBlock('YOUR NEXT SMALL WIN','Learning roadmap',`A practical path toward becoming a ${esc(state.role)}.`,'<button class="secondary-btn" data-action="generate-roadmap">✦ Refresh roadmap</button>')}<section class="card content-card" style="margin-bottom:17px"><div style="display:flex;justify-content:space-between;align-items:center"><div><h2>Your progress</h2><p class="muted">You’re moving forward. Keep the momentum going.</p></div><div style="text-align:right"><strong style="font:800 25px Manrope;color:var(--purple)">${pct}%</strong><div class="muted">${state.completed.length} of ${lessons.length} steps</div></div></div><div class="progress-track" style="height:8px;margin-top:13px"><div class="progress-fill" style="width:${pct}%"></div></div></section><div class="grid two-col"><section class="card content-card"><h2>Your learning path</h2><p class="muted">Recommended sequence · tailored to your target role</p>${lessons.map((l,i)=>`<div class="roadmap-item"><button class="roadmap-check ${state.completed.includes(i)?'done':''}" data-action="toggle-lesson" data-index="${i}" aria-label="Toggle ${esc(l[0])}">${state.completed.includes(i)?'✓':''}</button><div class="roadmap-copy"><strong>${esc(l[0])}</strong><p>${esc(l[1])}</p><small>${esc(l[2])}</small></div><span class="tag" style="align-self:flex-start">Step ${i+1}</span></div>`).join('')}</section><div><section class="card content-card"><h2>Tips for steady progress</h2><p class="muted">A little consistency makes the roadmap work for you.</p><div class="activity-list" style="padding:0"><div class="activity-item"><div class="activity-icon">⌚</div><div class="activity-copy"><strong>Set a weekly rhythm</strong><small>Even two focused hours can move a project forward.</small></div></div><div class="activity-item"><div class="activity-icon">✎</div><div class="activity-copy"><strong>Build while you learn</strong><small>Small demos make new concepts easier to remember.</small></div></div><div class="activity-item"><div class="activity-icon">↗</div><div class="activity-copy"><strong>Share your progress</strong><small>Update your portfolio as each milestone lands.</small></div></div></div></section><section class="card content-card section-gap"><h2>Target role</h2><p class="muted">Your roadmap is based on this goal.</p><select class="role-select" id="roleSelect" style="width:100%;margin-top:8px">${Object.keys(roles).map(r=>`<option ${state.role===r?'selected':''}>${r}</option>`).join('')}</select><button class="secondary-btn" data-page="skills" style="margin-top:12px">See skill analysis →</button></section></div></div>`}
function resumePage(){let result=state.analysis?`<div class="resume-result"><strong>Resume snapshot</strong><br/>${state.analysis}</div>`:'';return `${titleBlock('A FRESH SET OF EYES','Resume studio','Get a few practical suggestions to make your experience easier to understand.')}<div class="grid two-col"><section class="card content-card"><h2>Review your resume</h2><p class="muted">Choose a PDF, DOCX, or text file. Your file stays in this browser. No external AI service is connected in this demo.</p><label class="upload-zone" for="resumeFile"><div class="upload-icon">↑</div><strong>Choose a resume to review</strong><p>PDF, DOCX, or TXT · up to 10 MB</p><input id="resumeFile" type="file" accept=".pdf,.docx,.txt,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document,text/plain" hidden /></label><div style="display:flex;align-items:flex-start;gap:8px;margin:14px 0;color:#8d8fa0;font-size:10px;line-height:1.5"><input type="checkbox" id="resumeConsent" style="margin:0;accent-color:#7562e9"/><label for="resumeConsent">I understand that this local demo provides general checks only. Resume content is not sent to an AI provider.</label></div><button class="primary-btn" data-action="analyze-resume">✦ Review resume</button>${result}<div id="resumeStatus" class="muted" style="margin-top:10px"></div></section><div><section class="card content-card"><h2>What you’ll get</h2><p class="muted">A structured, local checklist to help you make your experience clearer.</p>${[['01','Clear summary','Does your opening explain what you do and where you’re headed?'],['02','Project impact','Do projects say what you built and why it matters?'],['03','Skills & keywords','Are relevant tools and role skills easy to find?'],['04','Next improvements','A few concrete ideas you can act on right away.']].map(x=>`<div class="roadmap-item"><span class="activity-icon">${x[0]}</span><div class="roadmap-copy"><strong>${x[1]}</strong><p>${x[2]}</p></div></div>`).join('')}</section><div class="notice section-gap">Your resume is sensitive personal information. This demo does not upload or transmit the selected file.</div></div></div>`}
function portfolioPage(){const p=state.profile, links=[['GitHub',p.github?.startsWith('http')?p.github:p.github?`https://github.com/${p.github}`:''],['LinkedIn',p.linkedin?.startsWith('http')?p.linkedin:p.linkedin?`https://linkedin.com/in/${p.linkedin}`:''],['LeetCode',p.leetcode?.startsWith('http')?p.leetcode:p.leetcode?`https://leetcode.com/u/${p.leetcode}`:''],['Website',p.website||'']].filter(x=>x[1]);const section=(title,value)=>value?.trim()?`<section class="card content-card portfolio-detail"><h2>${title}</h2><p>${esc(value)}</p></section>`:'';return `${titleBlock('YOUR WORK, BEAUTIFULLY PRESENTED','Student portfolio','A detailed portfolio preview assembled from your profile, education, projects, and achievements.')}<section class="card content-card portfolio-controls"><div><strong>Portfolio visibility</strong><p class="muted">${state.public?'Preview is marked public on this device.':'Preview is private on this device.'} This does not publish a public web link.</p></div><button class="secondary-btn" data-action="toggle-public">${state.public?'Public preview':'Make preview public'}</button></section><header class="portfolio-hero"><div class="portfolio-avatar">${initials(p.name)}</div><p class="eyebrow">STUDENT DEVELOPER &middot; ${esc(p.graduationYear||'')}</p><h2>${esc(p.name)}</h2><h3>${esc(p.title||'Student')}</h3><p class="portfolio-meta">${[p.degree,p.college,p.location].filter(Boolean).map(esc).join(' &middot; ')}</p><p class="portfolio-bio">${esc(p.bio||'Add a short introduction in My profile.')}</p><div class="portfolio-links">${links.map(([n,u])=>`<a href="${esc(u)}" target="_blank" rel="noreferrer">${esc(n)}</a>`).join('')}</div></header><div class="portfolio-section"><div class="portfolio-section-heading"><p class="eyebrow">SELECTED WORK</p><h2>Projects</h2></div><div class="grid two-col">${state.projects.map(p=>`<article class="card content-card portfolio-project"><div class="portfolio-project-top"><span class="project-status">${esc(p.status||'Project')}</span></div><h3>${esc(p.name)}</h3><p class="muted">${esc(p.description)}</p><div>${(p.tags||[]).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><div class="portfolio-link-row">${p.repo?`<a href="${esc(p.repo)}" target="_blank" rel="noreferrer">Source code ?</a>`:''}${p.demo?`<a href="${esc(p.demo)}" target="_blank" rel="noreferrer">Live demo ?</a>`:''}</div></article>`).join('')||'<div class="card content-card muted">Add projects to showcase your work.</div>'}</div></div><div class="grid two-col portfolio-details">${section('Education',[p.degree,p.college,p.graduationYear&&`Expected graduation: ${p.graduationYear}`].filter(Boolean).join(' &middot; ')||'Add your college, degree, and graduation year in My profile.')}${section('Relevant coursework',p.coursework)}${section('Experience',p.experience)}${section('Achievements',p.achievements)}${section('Career interests',p.interests)}<section class="card content-card portfolio-detail"><h2>Technical skills</h2><div>${(p.skills||[]).map(s=>`<span class="tag">${esc(s)}</span>`).join('')||'<p class="muted">Add skills in My profile.</p>'}</div></section><section class="card content-card portfolio-detail"><h2>Certifications</h2>${state.certifications.length?state.certifications.map(c=>`<p><strong>${esc(c.name)}</strong><br/><span class="muted">${esc(c.issuer)}${c.date?` &middot; ${esc(c.date)}`:''}</span>${c.url?` ? <a href="${esc(c.url)}" target="_blank" rel="noreferrer">Credential &rarr;</a>`:''}</p>`).join(''):'<p class="muted">Add certifications from Projects.</p>'}</section></div><div class="portfolio-footer">${p.email?`<a href="mailto:${esc(p.email)}">Contact ${esc(p.name.split(' ')[0])}</a>`:''}<button class="secondary-btn" data-action="copy-portfolio">? Copy portfolio text</button></div>`}
const pages={overview:dashboard,profile:profilePage,'developer-links':developerLinksPage,projects:projectsPage,skills:skillsPage,roadmap:roadmapPage,resume:resumePage,portfolio:portfolioPage};let current='overview';
function render(page=current){current=page in pages?page:'overview';document.getElementById('crumb').textContent=({overview:'Overview',profile:'My profile',projects:'Projects',skills:'Skill gap',roadmap:'Learning roadmap',resume:'Resume studio',portfolio:'Portfolio'})[current];document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===current));document.getElementById('pageContent').innerHTML=pages[current]();setIdentity();window.scrollTo(0,0)}
function modal(title,html,saveLabel='Save'){const d=document.getElementById('modal');document.getElementById('modalContent').innerHTML=`<div class="modal-inner"><div class="modal-head"><h2>${title}</h2><button class="close-modal" data-action="close-modal" aria-label="Close">×</button></div>${html}<div class="modal-actions"><button class="ghost-btn" data-action="close-modal">Cancel</button><button class="primary-btn" data-action="modal-save">${saveLabel}</button></div></div>`;d.showModal()}
function newProject(idx=null){let p=idx===null?{name:'',description:'',tags:[],status:'Completed',repo:'',demo:''}:state.projects[idx];modal(idx===null?'Add a project':'Edit project',`<form id="projectForm"><div class="field"><label>Project name</label><input name="name" required value="${esc(p.name)}" placeholder="e.g. A useful little app"/></div><div class="field"><label>Description</label><textarea name="description" required placeholder="What does it do? What did you learn?">${esc(p.description)}</textarea></div><div class="field"><label>Technologies (comma separated)</label><input name="tags" value="${esc((p.tags||[]).join(', '))}" placeholder="React, Node.js"/></div><div class="field"><label>Status</label><select name="status"><option ${p.status==='Completed'?'selected':''}>Completed</option><option ${p.status==='In progress'?'selected':''}>In progress</option></select></div><div class="field"><label>Repository URL</label><input name="repo" type="url" value="${esc(p.repo)}" placeholder="https://github.com/you/project"/></div><div class="field"><label>Live demo URL</label><input name="demo" type="url" value="${esc(p.demo)}" placeholder="https://example.com"/></div></form>`);document.getElementById('modal').dataset.projectIndex=idx===null?'':idx}
function exportWorkspacePdf(){const p=state.profile,escapeHtml=esc;const section=(title,body)=>body?`<section><h2>${escapeHtml(title)}</h2>${body}</section>`:'';const list=(items,render)=>items?.length?`<div class="items">${items.map(render).join('')}</div>`:'<p class="empty">No information added.</p>';const lines=(value)=>value?`<p>${escapeHtml(value)}</p>`:'';const profileRows=[['Name',p.name],['Title',p.title],['Email',p.email],['Location',p.location],['College / university',p.college],['Degree / major',p.degree],['Expected graduation',p.graduationYear],['Career interests',p.interests],['Website',p.website],['GitHub',p.github],['LinkedIn',p.linkedin],['LeetCode',p.leetcode]].filter(([,v])=>v).map(([k,v])=>`<div class="row"><b>${escapeHtml(k)}</b><span>${escapeHtml(v)}</span></div>`).join('');const html=`<!doctype html><html><head><meta charset="utf-8"><title>DevOrbit workspace export</title><style>*{box-sizing:border-box}body{max-width:800px;margin:36px auto;padding:0 28px;color:#26273b;font:14px/1.6 Arial,sans-serif}header{padding:25px 28px;border-radius:14px;background:#302c50;color:#fff}header h1{margin:0 0 5px;font-size:26px}header p{margin:0;color:#ddd8f2}h2{margin:24px 0 10px;padding-bottom:6px;border-bottom:1px solid #e8e6f1;font-size:17px;color:#5f4fc4}.row{display:flex;gap:14px;padding:5px 0}.row b{width:170px;flex:none}.row span{overflow-wrap:anywhere}.item{padding:10px 0;border-bottom:1px solid #eeeef3;break-inside:avoid}.item h3{margin:0;font-size:14px}.item p{margin:3px 0;color:#55586b;white-space:pre-line}.meta{font-size:12px;color:#6f7080}.tag{display:inline-block;margin:4px 4px 0 0;padding:3px 8px;border-radius:20px;background:#f0edff;color:#6552cf;font-size:11px}.empty{color:#888;font-style:italic}.print-tip{margin:16px 0;padding:10px 12px;background:#f6f4ff;border-radius:8px;color:#514c70;font-size:12px}@media print{body{margin:0 auto;padding:0 10mm}header{print-color-adjust:exact;-webkit-print-color-adjust:exact}.tag,.print-tip{print-color-adjust:exact;-webkit-print-color-adjust:exact}.print-tip{display:none}}@media(max-width:600px){body{margin:16px auto;padding:0 16px}.row{display:block}.row b{display:block;width:auto}}</style></head><body><header><h1>DevOrbit 360 | Workspace export</h1><p>${escapeHtml(p.name||'Student')} | Generated ${new Date().toLocaleDateString()}</p></header><p class="print-tip">In the print window, select <b>Save as PDF</b> for the destination.</p>${section('Student profile',`${profileRows}${p.bio?`<p>${escapeHtml(p.bio)}</p>`:''}`)}${section('Relevant coursework',lines(p.coursework))}${section('Experience',lines(p.experience))}${section('Achievements',lines(p.achievements))}${section('Technical skills',`<p>${(p.skills||[]).map(s=>`<span class="tag">${escapeHtml(s)}</span>`).join('')||'No skills added.'}</p>`)}${section('Projects',list(state.projects,x=>`<article class="item"><h3>${escapeHtml(x.name)}</h3><p>${escapeHtml(x.description)}</p><p class="meta">${escapeHtml((x.tags||[]).join(', '))} | ${escapeHtml(x.status||'')}</p>${x.repo?`<p class="meta">Repository: ${escapeHtml(x.repo)}</p>`:''}${x.demo?`<p class="meta">Live demo: ${escapeHtml(x.demo)}</p>`:''}</article>`))}${section('Certifications',list(state.certifications,x=>`<article class="item"><h3>${escapeHtml(x.name)}</h3><p>${escapeHtml(x.issuer||'')}${x.date?` | ${escapeHtml(x.date)}`:''}</p>${x.credential?`<p class="meta">Credential ID: ${escapeHtml(x.credential)}</p>`:''}${x.url?`<p class="meta">${escapeHtml(x.url)}</p>`:''}</article>`))}${section('Learning progress',`<p>Target role: ${escapeHtml(state.role||'')}</p><p>${state.completed.length} of ${lessons.length} roadmap steps completed (${Math.round(state.completed.length/lessons.length*100)}%).</p>${state.completed.map(i=>lessons[i]?`<p>- ${escapeHtml(lessons[i][0])}</p>`:'').join('')}`)}<script>window.addEventListener('load',()=>setTimeout(()=>window.print(),250))<\/script></body></html>`;const w=window.open('','_blank');if(!w){toast('Allow pop-ups to create your PDF export.');return}w.document.open();w.document.write(html);w.document.close();toast('Print-ready workspace opened. Choose Save as PDF.')}
function handleAction(action,el){switch(action){case'new-project':newProject();break;case'edit-project':newProject(Number(el.dataset.index));break;case'close-modal':document.getElementById('modal').close();break;case'modal-save':{const d=document.getElementById('modal'),idx=d.dataset.projectIndex;if(document.getElementById('projectForm')){const f=new FormData(document.getElementById('projectForm'));if(!f.get('name').trim()||!f.get('description').trim()){toast('Add a project name and description.');return}let p={name:f.get('name').trim(),description:f.get('description').trim(),tags:f.get('tags').split(',').map(t=>t.trim()).filter(Boolean),status:f.get('status'),repo:f.get('repo').trim(),demo:f.get('demo').trim()};if(idx==='')state.projects.unshift(p);else state.projects[Number(idx)]=p;state.activities.unshift({icon:'▧',text:`${idx===''?'Added':'Updated'} <strong>${esc(p.name)}</strong>`,time:'Just now'});save();d.close();render();toast('Project saved.')}else if(document.getElementById('certForm')){let f=new FormData(document.getElementById('certForm'));if(!f.get('name').trim()){toast('Add a certification name.');return}state.certifications.unshift({name:f.get('name').trim(),issuer:f.get('issuer').trim(),date:f.get('date'),credential:f.get('credential').trim(),url:f.get('url').trim()});save();d.close();render('projects');toast('Certification added.')}break}case'new-cert':modal('Add certification',`<form id="certForm"><div class="field"><label>Certification name</label><input name="name" required placeholder="e.g. Cloud Practitioner"/></div><div class="field"><label>Issuing organization</label><input name="issuer" placeholder="e.g. AWS"/></div><div class="field"><label>Issue date</label><input name="date" type="month"/></div><div class="field"><label>Credential ID</label><input name="credential"/></div><div class="field"><label>Credential URL</label><input name="url" type="url"/></div></form>`);break;case'delete-cert':state.certifications.splice(Number(el.dataset.index),1);save();render();toast('Certification removed.');break;case'save-profile':{let f=document.getElementById('profileForm');if(!f)break;let data=new FormData(f);for(let key of ['name','title','email','location','college','degree','graduationYear','coursework','interests','experience','achievements','website','github','linkedin','leetcode','bio'])state.profile[key]=String(data.get(key)||'').trim();save();render();toast('Profile saved.');break}case'add-skill':{let input=document.getElementById('newSkill'),v=input?.value.trim();if(v&&!state.profile.skills.some(s=>s.toLowerCase()===v.toLowerCase())){state.profile.skills.push(v);save();render();toast('Skill added.')}else if(v)toast('That skill is already on your profile.');break}case'remove-skill':state.profile.skills.splice(Number(el.dataset.index),1);save();render();toast('Skill removed.');break;case'learn-skill':if(!state.profile.skills.includes(el.dataset.skill))state.profile.skills.push(el.dataset.skill);save();render();toast(`${el.dataset.skill} added to your profile.`);break;case'toggle-lesson':{let i=Number(el.dataset.index);state.completed=state.completed.includes(i)?state.completed.filter(x=>x!==i):[...state.completed,i];save();render();toast('Roadmap progress updated.');break}case'generate-roadmap':render();toast('Your learning path is ready.');break;case'refresh-analysis':render();toast('Skill match recalculated from your profile.');break;case'toggle-public':state.public=!state.public;save();render();toast(state.public?'Portfolio preview marked public on this device.':'Portfolio preview set to private.');break;case'copy-portfolio':navigator.clipboard?.writeText(`${state.profile.name} — ${state.profile.title}\n${state.profile.bio}\nSkills: ${state.profile.skills.join(', ')}\nProjects: ${state.projects.map(p=>p.name).join(', ')}`).then(()=>toast('Portfolio text copied.')).catch(()=>toast('Clipboard access is unavailable here.'));break;case'sync-github':syncGithub();break;case'analyze-resume':analyzeResume();break}}
async function syncGithub(){let user=state.profile.github?.trim();if(!user){toast('Add your GitHub username to your profile first.');return}let target=document.getElementById('githubResult');target.innerHTML='<p class="muted">Connecting to GitHub…</p>';try{let resp=await fetch(`https://api.github.com/users/${encodeURIComponent(user)}/repos?sort=updated&per_page=20`);if(!resp.ok)throw new Error(resp.status===404?'GitHub user not found.':'GitHub is unavailable right now.');let repos=await resp.json();let added=0;for(let r of repos.slice(0,5)){if(state.projects.some(p=>p.repo===r.html_url))continue;state.projects.push({name:r.name,description:r.description||'Imported from GitHub.',tags:[r.language||'Code'],status:r.archived?'Completed':'In progress',repo:r.html_url,demo:r.homepage||''});added++}save();render();toast(`${added} GitHub repositories imported.`)}catch(e){target.innerHTML=`<div class="notice" style="margin-top:12px">${esc(e.message)} You can add projects manually, or try again later.</div>`}}
function analyzeResume(){let consent=document.getElementById('resumeConsent'),input=document.getElementById('resumeFile'),status=document.getElementById('resumeStatus');if(!consent?.checked){toast('Please confirm the resume privacy note first.');return}let file=input?.files?.[0];if(!file){toast('Choose a resume file to continue.');return}if(file.size>10*1024*1024){toast('This file is larger than 10 MB.');return}let text='';if(file.name.toLowerCase().endsWith('.txt')){let reader=new FileReader();reader.onload=()=>{state.analysis=resumeFeedback(String(reader.result||''));save();render();toast('Resume checklist is ready.');};reader.readAsText(file);return}state.analysis=`We received “${esc(file.name)}”. This browser-only demo does not parse PDF or DOCX content. Try a .txt file for a content-based checklist, or use these general suggestions: include a concise summary, describe project impact, and make role-relevant skills easy to scan.`;save();render();toast('Resume checklist is ready.')}
function resumeFeedback(t){let lower=t.toLowerCase(),checks=[];checks.push(lower.includes('summary')||lower.includes('objective')?'Your resume includes a summary or objective section.':'Consider adding a brief summary that names your target role.');checks.push(lower.includes('project')?'Project experience is mentioned. Add outcomes or measurable impact where possible.':'Add a projects section with what you built and the tools you used.');checks.push(lower.includes('experience')?'Experience is included. Keep bullet points focused on your contribution.':'If you have no formal experience yet, highlight coursework, volunteering, and projects.');let matched=state.profile.skills.filter(s=>lower.includes(s.toLowerCase()));checks.push(matched.length?`Found profile skills in the resume: ${matched.join(', ')}.`:'Make sure the skills you list match tools you can discuss confidently.');checks.push(`For a ${state.role} role, compare your resume with a real job posting and tailor relevant keywords honestly.`);return checks.map(x=>`• ${esc(x)}`).join('<br/>')}
document.addEventListener('click',e=>{let nav=e.target.closest('[data-page]');if(nav){e.preventDefault();render(nav.dataset.page);document.getElementById('sidebar').classList.remove('open');return}let action=e.target.closest('[data-action]');if(action){e.preventDefault();handleAction(action.dataset.action,action);return}let tip=e.target.closest('[data-toast]');if(tip)toast(tip.dataset.toast)});
document.addEventListener('change',e=>{if(e.target.id==='roleSelect'){state.role=e.target.value;save();render();toast('Target role updated.')}});
document.getElementById('mobileMenu').addEventListener('click',()=>document.getElementById('sidebar').classList.toggle('open'));
document.getElementById('modal').addEventListener('click',e=>{if(e.target.id==='modal')e.target.close()});
render('overview');

// Extended workspace modules: profile links, certificates, support and study assistant.
state.profile.githubUrl ||= state.profile.github?.startsWith('http') ? state.profile.github : state.profile.github ? `https://github.com/${state.profile.github}` : '';
state.profile.linkedinUrl ||= state.profile.linkedin?.startsWith('http') ? state.profile.linkedin : state.profile.linkedin ? `https://www.linkedin.com/in/${state.profile.linkedin}` : '';
state.profile.leetcodeUrl ||= state.profile.leetcode?.startsWith('http') ? state.profile.leetcode : state.profile.leetcode ? `https://leetcode.com/${state.profile.leetcode}` : '';
state.profile.websiteUrl ||= '';
state.profile.targetRole ||= state.role || 'MERN Stack Developer';
state.profile.linksStatus ||= {};
state.profile.leetcodeStats ||= {};
state.settings ||= {theme:'light',chatEndpoint:'',emailUpdates:false};
state.supportMessages ||= [];
state.chatHistory ||= [];
delete state.profile.location;
state.role = state.profile.targetRole;
save();

const oldRender = render;
render = function(page=current){
  oldRender(page);
  const labels={'developer-links':'Developer links',certifications:'Certifications',assistant:'AI study buddy',help:'Help center',settings:'Account settings'};
  if(labels[current]) document.getElementById('crumb').textContent=labels[current];
};

profilePage = function(){
  const fields=[['Full name','name'],['Professional title','title'],['Email address','email']];
  const pct=Math.min(100,Math.round((fields.filter(([,k])=>state.profile[k]).length+state.profile.skills.length+(state.profile.targetRole?1:0))/12*100));
  return `${titleBlock('YOUR DEVELOPER IDENTITY','My profile','Your career direction and skills, all in one place.','<button class="primary-btn" data-action="save-profile">Save changes</button>')}<div class="grid two-col"><section class="card content-card"><div class="profile-head"><div class="profile-avatar">${initials(state.profile.name)}</div><div><h2>${esc(state.profile.name)}</h2><span>${esc(state.profile.title)} · ${esc(state.profile.targetRole)}</span></div></div><div style="display:flex;justify-content:space-between;font-size:10px;color:#85889a;margin-bottom:8px"><span>Profile completeness</span><strong>${pct}%</strong></div><div class="progress-track"><div class="progress-fill" style="width:${pct}%"></div></div><div class="divider"></div><form id="profileForm"><div class="grid two-col">${fields.map(([label,key])=>`<div class="field"><label for="p_${key}">${label}</label><input id="p_${key}" name="${key}" value="${esc(state.profile[key]||'')}" /></div>`).join('')}<div class="field"><label for="p_targetRole">Target job role</label><select id="p_targetRole" name="targetRole">${Object.keys(roles).map(r=>`<option ${state.profile.targetRole===r?'selected':''}>${r}</option>`).join('')}</select></div></div><div class="field"><label for="p_bio">About you</label><textarea id="p_bio" name="bio">${esc(state.profile.bio)}</textarea></div><div class="divider"></div><h2 style="font:700 13px Manrope;margin:0 0 11px">Developer profile URLs</h2>${[['GitHub Profile URL','githubUrl','https://github.com/username'],['LinkedIn Profile URL','linkedinUrl','https://linkedin.com/in/username'],['LeetCode Profile URL','leetcodeUrl','https://leetcode.com/username'],['Personal Website / Portfolio URL','websiteUrl','https://yourwebsite.com']].map(([label,key,placeholder])=>`<div class="field"><label>${label}</label><input name="${key}" type="url" value="${esc(state.profile[key]||'')}" placeholder="${placeholder}"/></div>`).join('')}</form><button class="primary-btn" data-action="save-profile">Save profile</button></section><section class="card content-card"><h2>Your skills</h2><p class="muted">Keep your skills current so role matching stays useful.</p><div style="margin:13px 0">${state.profile.skills.map((s,i)=>`<span class="tag">${esc(s)} <button aria-label="Remove ${esc(s)}" data-action="remove-skill" data-index="${i}" style="border:0;background:none;color:inherit;padding:0 0 0 4px">×</button></span>`).join('')}</div><div class="field"><label for="newSkill">Add a skill</label><div style="display:flex;gap:7px"><input id="newSkill" placeholder="e.g. TypeScript"/><button class="secondary-btn" data-action="add-skill">Add</button></div></div><div class="divider"></div><h2 style="font:700 13px Manrope;margin-bottom:7px">Profile sync</h2><p class="muted">Connect and review your profile sources from the Developer links tab.</p><button class="secondary-btn" data-page="developer-links">Manage developer links →</button></section></div>`;
};

function developerLinksPage(){
  state.profile.linksStatus ||= {};
  state.profile.leetcodeStats ||= {};
  const rows=[['GitHub','githubUrl','github','Code and public repositories','github'],['LinkedIn','linkedinUrl','linkedin','Professional profile','linkedin'],['LeetCode','leetcodeUrl','leetcode','Coding practice profile','leetcode'],['Personal website','websiteUrl','website','Portfolio or personal site','website']];
  return `${titleBlock('CONNECTED PROFILE SOURCES','Developer links','Connect profile URLs and bring public developer information into your workspace.')}<section class="card content-card link-intro"><div class="link-intro-icon">✦</div><div><h2>One profile, all your work</h2><p class="muted">Paste profile URLs, save them, then sync sources that offer permitted access. Imported details remain editable.</p></div><button class="primary-btn" data-action="sync-all">↻ Sync available profiles</button></section><div class="grid two-col links-grid">${rows.map(([label,urlKey,legacy,desc,id])=>`<section class="card content-card link-card"><div class="link-card-top"><div class="link-brand ${id}">${id==='github'?'GH':id==='linkedin'?'in':id==='leetcode'?'LC':'↗'}</div><div class="link-title"><h2>${label}</h2><p>${desc}</p></div><span class="sync-badge ${state.profile.linksStatus[id]?'synced':''}">${state.profile.linksStatus[id]||'Not synced'}</span></div><div class="field"><label>${label} Profile URL</label><input id="link_${id}" type="url" value="${esc(state.profile[urlKey]||'')}" placeholder="${id==='github'?'https://github.com/username':id==='linkedin'?'https://linkedin.com/in/username':id==='leetcode'?'https://leetcode.com/username':'https://yourwebsite.com'}" /></div><div class="link-actions"><a class="text-link" href="${esc(state.profile[urlKey]||'#')}" target="_blank" rel="noreferrer" ${state.profile[urlKey]?'':'aria-disabled="true"'}>Open profile ↗</a><button class="secondary-btn" data-action="sync-link" data-source="${id}">Sync</button></div>${id==='leetcode' ? `<div class="manual-stats"><strong>Practice stats</strong><div class="grid three-col"><div class="field"><label>Solved</label><input type="number" min="0" id="lcSolved" value="${esc(state.profile.leetcodeStats.solved||'')}" placeholder="0"/></div><div class="field"><label>Easy</label><input type="number" min="0" id="lcEasy" value="${esc(state.profile.leetcodeStats.easy||'')}" placeholder="0"/></div><div class="field"><label>Medium</label><input type="number" min="0" id="lcMedium" value="${esc(state.profile.leetcodeStats.medium||'')}" placeholder="0"/></div></div><button class="text-link" data-action="save-leetcode-stats">Save stats</button></div>`:''}${id==='linkedin'||id==='website'?`<p class="link-note">${id==='linkedin'?'LinkedIn profile data requires approved API access. We never scrape private pages. Add details manually or use an authorized integration.':'External sites often block browser imports. Keep the URL here and add projects or skills manually when automatic access is unavailable.'}</p>`:''}</section>`).join('')}</div><section class="card content-card section-gap"><h2>Recent imported data</h2><p class="muted">GitHub repositories imported to your project list.</p>${state.projects.filter(p=>p.source==='github').map(p=>`<div class="project-row"><div class="project-main"><strong>${esc(p.name)}</strong><span>${esc(p.tags?.[0]||'Repository')} · ${esc(p.description||'')}</span></div><a class="text-link" href="${esc(p.repo)}" target="_blank" rel="noreferrer">Open ↗</a></div>`).join('')||'<div class="empty-state">No repositories imported yet. Sync your public GitHub profile to get started.</div>'}</section>`;
}

function certificationsPage(){return `${titleBlock('YOUR LEARNING MILESTONES','Certifications','Keep your credentials organized and easy to share.','<button class="primary-btn" data-action="new-cert">＋ Add certification</button>')}<div class="grid three-col certificate-grid">${state.certifications.map((c,i)=>`<section class="card certificate-card"><div class="certificate-ribbon">✦</div><div class="certificate-topline"><span class="tag">${esc(c.date||'Date not set')}</span><button class="more-button" aria-label="Remove certification" data-action="delete-cert" data-index="${i}">•••</button></div><h2>${esc(c.name)}</h2><p>${esc(c.issuer)}</p>${c.credential?`<small>Credential ID · ${esc(c.credential)}</small>`:''}<div class="certificate-footer">${c.url?`<a class="text-link" href="${esc(c.url)}" target="_blank" rel="noreferrer">View credential ↗</a>`:'<span class="muted">Credential link not added</span>'}<button class="text-link" data-action="delete-cert" data-index="${i}">Remove</button></div></section>`).join('')||'<section class="card empty-state"><strong>Your certificates will live here</strong>Add courses, badges, and credentials as you earn them.</section>'}<button class="card certificate-add" data-action="new-cert"><span>＋</span><strong>Add a certification</strong><small>Celebrate a new milestone</small></button></div>`}

projectsPage = function(){return `${titleBlock('YOUR WORK, IN ONE PLACE','Projects','Show the ideas you made real. Add the details you want recruiters to see.','<button class="primary-btn" data-action="new-project">＋ Add project</button>')}<div class="grid two-col">${state.projects.map((p,i)=>`<section class="card content-card project-detail-card"><div style="display:flex;justify-content:space-between"><div class="project-thumb" style="background:${i%2?'#eaf8f1':'#f1efff'};color:${i%2?'#48ab81':'#7562e9'}">${i%2?'◉':'▦'}</div><button class="more-button" data-action="edit-project" data-index="${i}" aria-label="Edit project">•••</button></div><h2 style="margin-top:13px">${esc(p.name)}</h2><p class="muted">${esc(p.description)}</p><div>${(p.tags||[]).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><div class="divider"></div><div style="display:flex;justify-content:space-between;align-items:center"><span class="project-status" style="${p.status==='In progress'?'background:#fff5e9;color:#dc963c':''}">${esc(p.status)}</span><div style="display:flex;gap:10px">${p.repo?`<a class="text-link" target="_blank" rel="noreferrer" href="${esc(p.repo)}">Repository ↗</a>`:''}${p.demo?`<a class="text-link" target="_blank" rel="noreferrer" href="${esc(p.demo)}">Live demo ↗</a>`:''}</div></div></section>`).join('')||'<section class="card card-empty">Nothing here yet. Add a project to get started.</section>'}</div>`};

function assistantPage(){return `${titleBlock('STUDY SUPPORT','AI study buddy','Ask about learning plans, interview prep, skill gaps, or your projects.')}<div class="grid assistant-layout"><section class="card chat-card"><div class="chat-header"><div class="chat-orb">✧</div><div><h2>Orbit assistant</h2><p><span class="online-dot"></span> ${state.settings.chatEndpoint?'AI service connected':'Career guide · demo mode'}</p></div><button class="text-link" data-action="clear-chat">Clear chat</button></div><div class="chat-messages" id="chatMessages">${state.chatHistory.length?state.chatHistory.map(m=>chatBubble(m.role,m.text)).join(''):chatBubble('assistant',`Hi ${esc(state.profile.name.split(' ')[0])}! I can help you plan your next learning step, understand your ${esc(state.role)} skill gaps, review project ideas, or prepare for interviews. What are you working on?`)}</div><div class="suggestion-row"><button data-action="chat-prompt" data-prompt="What should I learn next for my target role?">What should I learn next?</button><button data-action="chat-prompt" data-prompt="Help me prepare for a technical interview">Interview prep</button><button data-action="chat-prompt" data-prompt="Suggest a portfolio project based on my skills">Project idea</button></div><form id="chatForm" class="chat-compose"><textarea id="chatInput" rows="1" placeholder="Ask your study buddy…" aria-label="Message"></textarea><button class="primary-btn" type="submit">Send ↑</button></form></section><aside><section class="card content-card"><h2>Ask me about</h2><div class="topic-list"><button data-action="chat-prompt" data-prompt="Explain my skill gaps for ${esc(state.role)}">✦ &nbsp;Your skill gaps</button><button data-action="chat-prompt" data-prompt="Create a one-week study plan">⌁ &nbsp;Study plans</button><button data-action="chat-prompt" data-prompt="Give me mock interview questions for ${esc(state.role)}">◉ &nbsp;Interview practice</button><button data-action="chat-prompt" data-prompt="Review my project ideas">▧ &nbsp;Project feedback</button></div></section></aside></div>`}
function chatBubble(role,text){return `<div class="chat-message ${role==='user'?'user-message':'assistant-message'}"><span class="chat-avatar">${role==='user'?esc(initials(state.profile.name)):'✧'}</span><div class="chat-bubble">${esc(text).replace(/\n/g,'<br/>')}</div></div>`}
function helpPage(){let faqs=[['How do I connect GitHub?','Open Developer links, add your public GitHub profile URL, then choose Sync. DevOrbit imports public repositories through the GitHub REST API.'],['Why can’t LinkedIn sync automatically?','LinkedIn limits profile data to approved APIs and permissions. DevOrbit does not scrape private pages. You can save your profile URL and add relevant information manually.'],['Where is my resume stored?','Resume files are read in your browser for local analysis. DevOrbit does not send them to an AI provider in demo mode.'],['Can I publish a portfolio link?','The current preview is local to this browser. Public hosting needs a backend and a deployed site.']];return `${titleBlock('WE’RE HERE TO HELP','Help center','Find quick answers or send a support note.')}<div class="grid two-col"><section class="card content-card"><h2>Frequently asked questions</h2><div class="faq-list">${faqs.map(([q,a],i)=>`<details class="faq-item" ${i===0?'open':''}><summary>${q}<span>＋</span></summary><p>${a}</p></details>`).join('')}</div></section><section class="card content-card"><h2>Contact support</h2><p class="muted">Send a note about a problem or feature idea. In this demo, messages are saved on this device.</p><form id="supportForm"><div class="field"><label>Your email</label><input type="email" name="email" value="${esc(state.profile.email)}" required/></div><div class="field"><label>Topic</label><select name="topic"><option>Using DevOrbit</option><option>Report a problem</option><option>Feature suggestion</option><option>Privacy question</option></select></div><div class="field"><label>How can we help?</label><textarea name="message" required placeholder="Tell us a little about it…"></textarea></div><button class="primary-btn" type="submit">Send support note →</button></form><p class="muted" style="margin-top:12px">Saved support notes: ${state.supportMessages.length}</p></section></div>`}

function settingsPage(){return `${titleBlock('PREFERENCES','Account settings','Choose how DevOrbit looks and keep a printable copy of your workspace.')}<div class="settings-layout"><section class="card content-card settings-card"><div class="settings-card-icon">A</div><div class="settings-card-heading"><h2>Appearance</h2><p class="muted">Choose the theme used in this browser.</p></div><div class="field settings-theme-field"><label for="themeSelect">Color theme</label><select id="themeSelect"><option value="light" ${state.settings.theme==='light'?'selected':''}>Light</option><option value="dark" ${state.settings.theme==='dark'?'selected':''}>Dark</option><option value="system" ${state.settings.theme==='system'?'selected':''}>Use device setting</option></select></div><button class="primary-btn" data-action="save-settings">Save appearance</button></section><section class="card content-card settings-card"><div class="settings-card-icon data-icon">PDF</div><div class="settings-card-heading"><h2>Your data</h2><p class="muted">Create a print-ready PDF with your profile, education, skills, projects, certifications, and learning progress.</p></div><div class="export-includes"><span>Student profile</span><span>Projects & links</span><span>Certificates</span><span>Learning progress</span></div><button class="primary-btn" data-action="export-data">Export workspace as PDF</button><p class="settings-footnote">Your browser's print window will open. Choose <strong>Save as PDF</strong> as the destination.</p></section></div><div class="settings-session-action settings-signout"><div><strong>Sign out</strong><small>End your session on this device.</small></div><button class="danger-btn" type="button" data-logout>Sign out</button></div>`}
pages['profile']=profilePage;pages['developer-links']=developerLinksPage;pages['projects']=projectsPage;pages['certifications']=certificationsPage;pages['assistant']=assistantPage;pages['help']=helpPage;pages['settings']=settingsPage;

const priorAction=handleAction;
handleAction=async function(action,el){
  if(action==='save-profile'){
    const f=document.getElementById('profileForm');if(!f)return;const d=new FormData(f);
    for(const k of ['name','title','email','bio','githubUrl','linkedinUrl','leetcodeUrl','websiteUrl'])state.profile[k]=String(d.get(k)||'').trim();
    state.profile.targetRole=String(d.get('targetRole')||'MERN Stack Developer');state.role=state.profile.targetRole;
    state.profile.github=state.profile.githubUrl;state.profile.linkedin=state.profile.linkedinUrl;state.profile.leetcode=state.profile.leetcodeUrl;
    save();render();toast('Profile saved.');return;
  }
  if(action==='sync-link'){await syncLink(el.dataset.source);return}
  if(action==='sync-all'){for(const source of ['github','leetcode','linkedin','website'])await syncLink(source);return}
  if(action==='save-leetcode-stats'){state.profile.leetcodeStats={solved:document.getElementById('lcSolved').value,easy:document.getElementById('lcEasy').value,medium:document.getElementById('lcMedium').value};state.profile.linksStatus.leetcode='Manually updated';save();render();toast('LeetCode stats saved.');return}
  if(action==='new-cert'&&current==='certifications'){modal('Add certification',`<form id="certForm"><div class="field"><label>Certification name</label><input name="name" required placeholder="e.g. Cloud Practitioner"/></div><div class="field"><label>Issuing organization</label><input name="issuer" placeholder="e.g. AWS"/></div><div class="field"><label>Issue date</label><input name="date" type="month"/></div><div class="field"><label>Credential ID</label><input name="credential"/></div><div class="field"><label>Credential URL</label><input name="url" type="url"/></div></form>`);return}
  if(action==='modal-save'&&document.getElementById('certForm')){const d=new FormData(document.getElementById('certForm'));if(!d.get('name').trim()){toast('Add a certification name.');return}state.certifications.unshift({name:d.get('name').trim(),issuer:d.get('issuer').trim(),date:d.get('date'),credential:d.get('credential').trim(),url:d.get('url').trim()});save();document.getElementById('modal').close();render('certifications');toast('Certification added.');return}
  if(action==='save-settings'){state.settings.theme=document.getElementById('themeSelect').value;save();applyTheme();render();toast('Appearance saved.');return}
  if(action==='export-data'){exportWorkspacePdf();return}
  if(action==='chat-prompt'){document.getElementById('chatInput').value=el.dataset.prompt;document.getElementById('chatInput').focus();return}
  if(action==='clear-chat'){state.chatHistory=[];save();render();toast('Chat history cleared.');return}
  if(action==='toggle-public'){state.public=!state.public;save();render();toast(state.public?'Portfolio preview marked public on this device.':'Portfolio preview set to private.');return}
  return priorAction(action,el);
};

async function syncLink(source){
  const key={github:'githubUrl',linkedin:'linkedinUrl',leetcode:'leetcodeUrl',website:'websiteUrl'}[source];const input=document.getElementById(`link_${source}`);if(input)state.profile[key]=input.value.trim();const url=state.profile[key];
  if(!url){toast(`Add your ${source==='website'?'website':source} URL first.`);return}
  if(source==='github'){
    const match=url.match(/github\.com\/([\w-]+)/i);if(!match){toast('Enter a valid GitHub profile URL.');return}const user=match[1];toast('Syncing public GitHub repositories…');
    try{const response=await fetch(`https://api.github.com/users/${encodeURIComponent(user)}/repos?sort=updated&per_page=30`);if(!response.ok)throw new Error(response.status===404?'GitHub profile not found.':'GitHub API unavailable or rate limited.');const repos=await response.json();let count=0;for(const repo of repos.slice(0,12)){if(state.projects.some(p=>p.repo===repo.html_url))continue;state.projects.push({name:repo.name,description:repo.description||'Imported from public GitHub repository.',tags:[repo.language||'Code'],status:repo.archived?'Completed':'In progress',repo:repo.html_url,demo:repo.homepage||'',source:'github'});count++}state.profile.linksStatus.github=`Synced ${new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}`;state.profile.github=url;save();render('developer-links');toast(`${count} new GitHub repositories imported.`)}catch(e){save();toast(e.message)}return;
  }
  if(source==='leetcode'){
    const match=url.match(/leetcode\.com\/(?:u\/)?([\w-]+)/i);if(!match){toast('Enter a valid LeetCode profile URL.');return}
    try{const response=await fetch(`https://leetcode-stats-api.herokuapp.com/${encodeURIComponent(match[1])}`);if(!response.ok)throw new Error('No supported public stats source responded.');const data=await response.json();if(data.status!=='success')throw new Error('LeetCode stats are not available for this profile.');state.profile.leetcodeStats={solved:data.totalSolved,easy:data.easySolved,medium:data.mediumSolved,hard:data.hardSolved};state.profile.linksStatus.leetcode=`Synced ${new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}`;state.profile.leetcode=url;save();render('developer-links');toast(`LeetCode stats synced · ${data.totalSolved} solved.`)}catch{state.profile.linksStatus.leetcode='Manual stats available';save();render('developer-links');toast('Live LeetCode sync is unavailable. You can enter the stats manually.')}return;
  }
  state.profile.linksStatus[source]=source==='linkedin'?'URL saved · API access required':'URL saved · external import restricted';if(source==='linkedin')state.profile.linkedin=url;save();render('developer-links');toast(source==='linkedin'?'LinkedIn URL saved. Profile data requires approved API access.':'Website URL saved. External imports may be blocked by browser security.');
}

function applyTheme(){document.documentElement.dataset.theme=state.settings.theme||'light'}
applyTheme();
document.addEventListener('change',e=>{if(e.target.id==='roleSelect'){state.role=e.target.value;state.profile.targetRole=e.target.value;save()}},true);
document.addEventListener('input',e=>{if(e.target.id==='link_github')state.profile.githubUrl=e.target.value;if(e.target.id==='link_linkedin')state.profile.linkedinUrl=e.target.value;if(e.target.id==='link_leetcode')state.profile.leetcodeUrl=e.target.value;if(e.target.id==='link_website')state.profile.websiteUrl=e.target.value});
document.addEventListener('submit',async e=>{
  if(e.target.id==='chatForm'){e.preventDefault();const input=document.getElementById('chatInput'),message=input.value.trim();if(!message)return;input.value='';state.chatHistory.push({role:'user',text:message});save();render('assistant');
    let answer;try{if(state.settings.chatEndpoint){const response=await fetch(state.settings.chatEndpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message,profile:{role:state.role,skills:state.profile.skills,projects:state.projects.map(p=>p.name)}})});if(!response.ok)throw new Error('AI service did not respond.');const data=await response.json();answer=data.reply||data.answer||data.message||'The AI endpoint returned no reply.'}else answer=offlineAnswer(message)}catch{answer='I could not reach the configured AI service. Check its URL and make sure your server accepts this website’s requests. You can clear the endpoint to use the built-in study guide.'}
    state.chatHistory.push({role:'assistant',text:answer});save();render('assistant');document.getElementById('chatMessages').scrollTop=99999;return;
  }
  if(e.target.id==='supportForm'){e.preventDefault();const d=new FormData(e.target);state.supportMessages.unshift({email:d.get('email'),topic:d.get('topic'),message:d.get('message'),date:new Date().toISOString()});save();render('help');toast('Support note saved on this device.');return;}
});
function offlineAnswer(message){const m=message.toLowerCase(),skills=state.profile.skills.join(', '),role=state.role,gaps=(roles[role]||[]).filter(s=>!state.profile.skills.includes(s));if(/hello|hi\b|hey/.test(m))return `Hi ${state.profile.name.split(' ')[0]}! What are you learning or building today?`;if(/skill|gap|role|learn next/.test(m))return `For your ${role} goal, your profile currently lists: ${skills||'no skills yet'}. Skills still to explore include ${gaps.slice(0,5).join(', ')||'you have matched the current checklist'}. Pick one gap and build a small project around it; this checklist is a guide, not a proficiency score.`;if(/interview|mock/.test(m))return `Let's practice for a ${role} interview. Try explaining: (1) how you would design a REST API for one of your projects, (2) how you handle errors and validation, and (3) what trade-offs you made in a recent build. Answer one and I’ll help you refine it.`;if(/project|portfolio/.test(m))return `Based on your ${skills||'developer'} profile, build a small ${role.includes('Data')?'data dashboard':'full-stack application'} that solves a real student problem. Include a clear README, tests for core behavior, a live demo, and a short explanation of one design decision. You have ${state.projects.length} projects in your workspace to build from.`;if(/plan|week|study|roadmap/.test(m))return `A manageable one-week plan for ${role}: spend two short sessions on ${gaps[0]||'your strongest skill'}, one session practicing fundamentals, then build a tiny feature that uses it. Finish by writing down what worked and what you want to revisit. Mark roadmap steps complete as you go.`;if(/resume|cv/.test(m))return `For your resume, make your target role (${role}) easy to spot, describe projects with action and outcomes, and list tools you can discuss confidently. Resume Studio can scan PDF, DOCX, and TXT locally in this browser; your file is not sent to an AI service.`;return `For ${role} preparation, start with one concrete question: what outcome do you want this week? Your current skills are ${skills||'not added yet'}. I can help with learning plans, skill gaps, interview practice, projects, and resumes. This guided demo uses your saved profile; connect a server AI endpoint in Account settings for open-ended generated responses.`}

const oldAnalyzeResume=analyzeResume;
analyzeResume=async function(){const consent=document.getElementById('resumeConsent'),input=document.getElementById('resumeFile');if(!consent?.checked){toast('Please confirm the privacy note first.');return}const file=input?.files?.[0];if(!file){toast('Choose a resume file to continue.');return}if(file.size>10*1024*1024){toast('This file is larger than 10 MB.');return}const name=file.name.toLowerCase();try{let text='';if(name.endsWith('.txt'))text=await file.text();else if(name.endsWith('.pdf'))text=await extractPdf(file);else if(name.endsWith('.docx'))text=await extractDocx(file);else throw new Error('Please select a PDF, DOCX, or TXT file.');if(!text.trim())throw new Error('No readable text found. This file may be image-only; run OCR first, then upload a text-based PDF.');state.analysis=`Scanned ${esc(file.name)} · ${text.trim().split(/\s+/).length} words<br/><br/>${resumeFeedback(text)}`;save();render('resume');toast('Resume scan complete. The file was processed locally.')}catch(e){toast(e.message||'Could not read that resume.')}};
function loadScript(src,id){return new Promise((resolve,reject)=>{if(document.getElementById(id)){resolve();return}const s=document.createElement('script');s.id=id;s.src=src;s.onload=resolve;s.onerror=()=>reject(new Error('Could not load the document reader. Check your internet connection and try again.'));document.head.appendChild(s)})}
async function extractPdf(file){await loadScript('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js','pdfjs-lib');if(!window.pdfjsLib)throw new Error('PDF reader could not start.');window.pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';const doc=await window.pdfjsLib.getDocument({data:await file.arrayBuffer()}).promise;let text='';for(let i=1;i<=doc.numPages;i++){const page=await doc.getPage(i),content=await page.getTextContent();text+=content.items.map(x=>x.str).join(' ')+'\n'}return text}
async function extractDocx(file){await loadScript('https://cdnjs.cloudflare.com/ajax/libs/mammoth/1.8.0/mammoth.browser.min.js','mammoth-lib');if(!window.mammoth)throw new Error('DOCX reader could not start.');const result=await window.mammoth.extractRawText({arrayBuffer:await file.arrayBuffer()});return result.value}

// The resume service stores the uploaded file and returns a role-specific skill analysis.
resumePage=function(){
  const resume=state.resume;
  const analysis=state.analysis;
  const result=analysis?`<div class="resume-result"><strong>${esc(analysis.provider||'Resume analysis')}</strong><p>${esc(analysis.summary||'')}</p>${analysis.skills?.length?`<div class="resume-skills">${analysis.skills.map(skill=>`<span class="tag">${esc(skill)}</span>`).join('')}</div>`:''}${analysis.strengths?.length?`<strong>Strengths</strong><ul>${analysis.strengths.map(item=>`<li>${esc(item)}</li>`).join('')}</ul>`:''}${analysis.improvements?.length?`<strong>Ways to improve</strong><ul>${analysis.improvements.map(item=>`<li>${esc(item)}</li>`).join('')}</ul>`:''}<button class="primary-btn" data-page="roadmap">View my learning roadmap →</button></div>`:'';
  return `${titleBlock('A FRESH SET OF EYES','Resume studio','Upload a resume to find role-relevant skills and build your next learning steps.')}<div class="grid two-col"><section class="card content-card"><h2>Resume review</h2><p class="muted">PDF, DOCX, or TXT · up to 10 MB. Your file is stored with your account for analysis.</p><label class="upload-zone" for="resumeFile"><div class="upload-icon">↑</div><strong>Choose a resume</strong><p>Browse your device for a file</p><input id="resumeFile" type="file" accept=".pdf,.docx,.txt,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document,text/plain" hidden /></label><div id="resumeFilePreview" class="resume-file-preview" ${resume?'':'hidden'}><span class="resume-file-icon">▤</span><span><strong>${esc(resume?.name||'')}</strong><small>${resume?`${(resume.size/1024/1024).toFixed(2)} MB · saved to your account`:''}</small></span></div>${resume?'<div class="resume-actions"><button class="secondary-btn" data-action="view-resume">View uploaded resume ↗</button><button class="danger-btn" data-action="remove-resume">Remove resume</button></div>':''}<div class="field" style="margin-top:16px"><label for="resumeRole">Target job role</label><select id="resumeRole" class="role-select">${Object.keys(roles).map(role=>`<option ${state.role===role?'selected':''}>${esc(role)}</option>`).join('')}</select></div><div class="privacy-consent"><input type="checkbox" id="resumeConsent"/><label for="resumeConsent">I agree to upload my resume for analysis. Resume text may be sent to the configured AI provider when an AI key is enabled.</label></div><button class="primary-btn" data-action="analyze-resume">✦ Analyze resume</button>${result}<div id="resumeStatus" class="muted" style="margin-top:10px"></div></section><div><section class="card content-card"><h2>What you’ll get</h2><p class="muted">A practical review tailored to your target role.</p>${[['01','Skills found','Relevant skills identified in the resume.'],['02','Resume feedback','Strengths and concrete improvements.'],['03','Skill gaps','Compare skills with your target role.'],['04','Learning roadmap','A sequenced path to build the missing skills.']].map(item=>`<div class="roadmap-item"><span class="activity-icon">${item[0]}</span><div class="roadmap-copy"><strong>${item[1]}</strong><p>${item[2]}</p></div></div>`).join('')}</section></div></div>`;
};
pages.resume=resumePage;
roadmapPage=function(){
  const items=state.roadmap?.length?state.roadmap:lessons.map(([title,description,duration])=>({title,description,duration}));
  const completed=state.completed||[];const pct=Math.round(completed.length/items.length*100);
  return `${titleBlock('YOUR NEXT SMALL WIN','Learning roadmap',`A practical path toward becoming a ${esc(state.role)}.`,'<button class="secondary-btn" data-page="resume">✦ Analyze another resume</button>')}<section class="card content-card" style="margin-bottom:17px"><div style="display:flex;justify-content:space-between;align-items:center"><div><h2>Your progress</h2><p class="muted">${state.roadmap?.length?'Personalized using your resume skills and target role.':'Your starter learning path is ready.'}</p></div><div style="text-align:right"><strong style="font:800 25px Manrope;color:var(--purple)">${pct}%</strong><div class="muted">${completed.length} of ${items.length} steps</div></div></div><div class="progress-track" style="height:8px;margin-top:13px"><div class="progress-fill" style="width:${pct}%"></div></div></section><div class="grid two-col"><section class="card content-card"><h2>Your learning path</h2><p class="muted">Recommended sequence · tailored to your target role</p>${items.map((item,i)=>`<div class="roadmap-item"><button class="roadmap-check ${completed.includes(i)?'done':''}" data-action="toggle-lesson" data-index="${i}" aria-label="Toggle ${esc(item.title)}">${completed.includes(i)?'✓':''}</button><div class="roadmap-copy"><strong>${esc(item.title)}</strong><p>${esc(item.description)}</p><small>${esc(item.duration||'Self-paced')}</small></div><span class="tag" style="align-self:flex-start">Step ${i+1}</span></div>`).join('')}</section><section class="card content-card"><h2>Skills from your resume</h2><p class="muted">Use these as the starting point for your next projects.</p><div>${(state.analysis?.skills||state.profile.skills).map(skill=>`<span class="tag">${esc(skill)}</span>`).join('')}</div><div class="divider"></div><h2>Target role</h2><p class="muted">Change the role to regenerate your skill comparison.</p><select class="role-select" id="roleSelect" style="width:100%">${Object.keys(roles).map(role=>`<option ${state.role===role?'selected':''}>${esc(role)}</option>`).join('')}</select><button class="secondary-btn" data-page="skills" style="margin-top:12px">See skill analysis →</button></section></div>`;
};
pages.roadmap=roadmapPage;
const originalSettingsPage=settingsPage;
settingsPage=function(){return originalSettingsPage().replace('Manage your local profile data and workspace preferences.','Manage your account, workspace data, and preferences.').replace('Your preferences apply to this browser.','Your account and workspace data are saved to MongoDB.').replace('This static demo saves profile information in your browser’s local storage.','Your profile and career workspace are saved to your account.').replace('No login account or server-side account data exists in this demo. Clearing browser data also clears your DevOrbit workspace.','Your workspace belongs to your signed-in account. Use the sign-out button in the sidebar when you are done.').replace('<div class="notice">Your workspace belongs to your signed-in account. Use the sign-out button in the sidebar when you are done.</div>','<div class="settings-session-action"><div><strong>Sign out</strong><small>End your session on this device.</small></div><button class="danger-btn" type="button" data-logout>Sign out</button></div>')};
pages.settings=settingsPage;
document.addEventListener('change',event=>{
  if(event.target.id==='resumeFile'){const preview=document.getElementById('resumeFilePreview'),file=event.target.files?.[0];if(preview&&file){preview.hidden=false;preview.innerHTML=`<span class="resume-file-icon">▤</span><span><strong>${esc(file.name)}</strong><small>${(file.size/1024/1024).toFixed(2)} MB · ready to upload</small></span>`}}
  if(event.target.id==='resumeRole'){state.role=event.target.value;state.profile.targetRole=state.role;save()}
});
analyzeResume=async function(){
  const file=document.getElementById('resumeFile')?.files?.[0];if(!file){toast('Choose a resume file to continue.');return}if(!document.getElementById('resumeConsent')?.checked){toast('Please agree to the resume upload first.');return}if(file.size>10*1024*1024){toast('This file is larger than 10 MB.');return}
  const button=document.querySelector('[data-action="analyze-resume"]');if(button){button.disabled=true;button.textContent='Analyzing resume…'}
  try{const form=new FormData();form.append('resume',file);form.append('role',document.getElementById('resumeRole')?.value||state.role);const response=await fetch('/api/resume/analyze',{method:'POST',headers:{Authorization:`Bearer ${window.DevOrbitAuth?.token?.()||''}`},body:form});const data=await response.json();if(!response.ok)throw new Error(data.error||'Resume analysis failed.');state.resume=data.resume;state.analysis=data.analysis;state.roadmap=data.roadmap;state.profile.skills=data.workspace.profile.skills;state.role=state.profile.targetRole=document.getElementById('resumeRole')?.value||state.role;state.completed=[];save();render('resume');toast(data.analysis.provider?.includes('AI analysis')?'AI resume analysis complete.':'Resume reviewed with built-in fallback; see the status in the results.')}catch(error){toast(error.message||'Could not analyze this resume.');if(button){button.disabled=false;button.textContent='✦ Analyze resume'}}
};
const previousHandleAction=handleAction;
handleAction=async function(action,element){
  if(action==='view-resume'){try{const response=await fetch(`/api/resume/${encodeURIComponent(state.resume.id)}`,{headers:{Authorization:`Bearer ${window.DevOrbitAuth?.token?.()||''}`}});if(!response.ok)throw new Error('Could not open your saved resume.');const url=URL.createObjectURL(await response.blob());window.open(url,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(url),60000)}catch(error){toast(error.message)}return}
  if(action==='remove-resume'){if(!state.resume)return;const button=element;button.disabled=true;button.textContent='Removing…';try{const response=await fetch(`/api/resume/${encodeURIComponent(state.resume.id)}`,{method:'DELETE',headers:{Authorization:`Bearer ${window.DevOrbitAuth?.token?.()||''}`}});const data=await response.json();if(!response.ok)throw new Error(data.error||'Could not remove the resume.');state.resume=null;state.analysis=null;state.roadmap=null;state.completed=[];save();render('resume');toast('Resume removed. You can upload another now.')}catch(error){button.disabled=false;button.textContent='Remove resume';toast(error.message)}return}
  if(action==='toggle-lesson'&&state.roadmap?.length){const index=Number(element.dataset.index);state.completed=state.completed.includes(index)?state.completed.filter(i=>i!==index):[...state.completed,index];save();render('roadmap');return}
  if(action==='analyze-resume'){await analyzeResume();return}
  return previousHandleAction(action,element);
};
window.addEventListener('devorbit:authenticated',event=>{
  const workspace=event.detail;if(workspace){state={...seed,...workspace};state.profile={...seed.profile,...(workspace.profile||{})};state.settings={theme:'light',chatEndpoint:'',emailUpdates:false,...(workspace.settings||{})};state.projects=workspace.projects||seed.projects;state.certifications=workspace.certifications||[];state.completed=workspace.completed||[];state.role=state.profile.targetRole||workspace.role||'MERN Stack Developer';state.profile.targetRole=state.role;state.supportMessages=workspace.supportMessages||[];state.chatHistory=workspace.chatHistory||[];state.roadmap=workspace.roadmap||null;state.resume=workspace.resume||null;state.analysis=workspace.analysis||null;localStorage.setItem('devorbit-state',JSON.stringify(state))}
  window.DevOrbitAuth?.hide();applyTheme();render('overview');
});
document.addEventListener('click',event=>{const logout=event.target.closest('[data-logout]');if(logout){event.preventDefault();window.dispatchEvent(new Event('devorbit:logout'));window.DevOrbitAuth?.logout()}});
document.addEventListener('click',event=>{const toggle=event.target.closest('#profileMenuToggle');if(!toggle)return;const menu=toggle.closest('.profile-menu');const open=menu.classList.toggle('open');toggle.setAttribute('aria-expanded',String(open))});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){const menu=document.getElementById('profileMenu');if(menu){menu.classList.remove('open');document.getElementById('profileMenuToggle')?.setAttribute('aria-expanded','false')}}});
render('overview');
